 S.expire(f,1,k=>{expired.push(k);S.apply(f,'中毒',1,1);});assert.deepEqual(expired,['麻痹']);assert.equal(f.ailments['中毒'],1);assert.equal(f.ailments['麻痹'],undefined);
});

